```sh
/bin/bash -lc python3 - <<'PY'
from functools import lru_cache

n=16
adj=[[] for _ in range(n)]
for i in range(n):
    for j in range(n):
        if i!=j:
            x=i^j
            hw=x.bit_count()
            if hw in (1,2):
                adj[i].append(j)

size=1<<n
# dp[mask][v]: number of paths from 0 to v using exactly mask, with 0 included and v in mask
# mask bit 0 always set
# use dicts by mask size iteration to stay reasonable
from collections import defaultdict

dp=[defaultdict(int) for _ in range(size)]
dp[1][0]=1
for mask in range(size):
    if not (mask&1):
        continue
    d=dp[mask]
    if not d:
        continue
    for v,cnt in list(d.items()):
        for w in adj[v]:
            if mask>>w & 1:
                continue
            dp[mask | (1<<w)][w] += cnt

full=size-1
ans=0
for v,cnt in dp[full].items():
    if v!=0 and 0 in adj[v]:
        ans += cnt
print(ans)
PY
```

