from math import gcd

def count_cyclic_words(d,q,m,target=0):
    # sequences x_0..x_{d-1} in [0,q), adjacent unequal cyclically, sum mod m = target
    # DP over first color, last color, residue
    ans=[0]*m
    for first in range(q):
        dp=[[0]*m for _ in range(q)]
        dp[first][first % m]=1
        for _ in range(1,d):
            ndp=[[0]*m for _ in range(q)]
            for last in range(q):
                row=dp[last]
                for s,val in enumerate(row):
                    if not val: continue
                    for x in range(q):
                        if x!=last:
                            ndp[x][(s+x)%m] += val
            dp=ndp
        for last in range(q):
            if last==first: continue
            for s,val in enumerate(dp[last]):
                ans[s]+=val
    return ans

def burnside_rot(n,q,m,target=0):
    total=0
    div_cache={}
    for k in range(n):
        d=gcd(n,k)
        t=n//d
        if d not in div_cache:
            div_cache[d]=count_cyclic_words(d,q,m)
        cnts=div_cache[d]
        total += sum(c for r,c in enumerate(cnts) if (t*r-target)%m==0)
    return total//n

