#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;

struct Counter {
    static constexpr int N0=7, E=21, W=35; // K7 + extension to vertex 7
    vector<pair<int,int>> edges;
    vector<array<int,2>> triPairs[E];
    uint64_t allow[E][3][W];
    uint64_t targetMask[8][8][8][W];
    int color[E];
    int target[3];
    long long nodes=0;

    Counter(){
        int idx[N0][N0]; memset(idx,-1,sizeof(idx));
        for(int i=0;i<N0;i++) for(int j=i+1;j<N0;j++){
            idx[i][j]=idx[j][i]=edges.size();
            edges.push_back({i,j});
        }
        for(int e=0;e<E;e++){
            auto [u,v]=edges[e];
            for(int w=0;w<N0;w++) if(w!=u && w!=v){
                int e1=idx[min(u,w)][max(u,w)], e2=idx[min(v,w)][max(v,w)];
                if(e1<e2) triPairs[e].push_back({e1,e2}); else triPairs[e].push_back({e2,e1});
            }
            sort(triPairs[e].begin(), triPairs[e].end(), [](auto&a,auto&b){return a[0]==b[0]?a[1]<b[1]:a[0]<b[0];});
            triPairs[e].erase(unique(triPairs[e].begin(), triPairs[e].end(), [](auto&a,auto&b){return a[0]==b[0]&&a[1]==b[1];}), triPairs[e].end());
        }
        memset(allow,0,sizeof(allow));
        for(int code=0; code<2187; code++){
            int t=code,x[N0];
            int cnt[3]={0,0,0};
            for(int i=0;i<N0;i++){ x[i]=t%3; cnt[x[i]]++; t/=3; }
            for(int e=0;e<E;e++){
                auto [u,v]=edges[e];
                for(int c=0;c<3;c++) if(!(x[u]==c && x[v]==c)) allow[e][c][code>>6] |= 1ULL<<(code&63);
            }
            for(int a=0;a<=7;a++) for(int b=0;b<=7;b++) for(int c=0;c<=7;c++){}
            targetMask[cnt[0]][cnt[1]][cnt[2]][code>>6] |= 1ULL<<(code&63);
        }
        memset(color,-1,sizeof(color));
    }

    ull dfs(int pos, int c0, int c1, int c2, const uint64_t *bits){
        nodes++;
        if(c0>target[0] || c1>target[1] || c2>target[2]) return 0;
        int rem = E-pos;
        // residual extension counts must be in [0,7]
        int need0 = target[0]-c0, need1 = target[1]-c1, need2 = target[2]-c2;
        if(need0<0||need1<0||need2<0) return 0;
        if(need0>rem+7 || need1>rem+7 || need2>rem+7) return 0;
        // At least sum of needs from K7 edges after extension? sum(need)=rem+7 always if targets sum 28. so okay.
        if(pos==E){
            if(need0>7 || need1>7 || need2>7) return 0;
            ull cnt=0;
            for(int w=0;w<W;w++) cnt += __builtin_popcountll(bits[w] & targetMask[need0][need1][need2][w]);
            return cnt;
        }
        int e=pos;
        bool forb[3]={false,false,false};
        for(auto &pr: triPairs[e]){
            int cA=color[pr[0]], cB=color[pr[1]];
            if(cA!=-1 && cA==cB) forb[cA]=true;
        }
        ull total=0;
        uint64_t nb[W];
        for(int c=0;c<3;c++) if(!forb[c]){
            bool any=false;
            for(int w=0;w<W;w++) { nb[w]=bits[w] & allow[e][c][w]; any |= (nb[w]!=0); }
            if(!any) continue;
            color[e]=c;
            total += dfs(pos+1, c0+(c==0), c1+(c==1), c2+(c==2), nb);
            color[e]=-1;
        }
        return total;
    }

    ull count(int a,int b,int c){
        target[0]=a; target[1]=b; target[2]=c;
        uint64_t full[W]; for(int i=0;i<W;i++) full[i]=~0ULL; full[W-1]=(1ULL<<11)-1ULL;
        nodes=0;
        return dfs(0,0,0,0,full);
    }
};

int main(int argc,char**argv){
    Counter ctr;
    if(argc==4){
        int a=stoi(argv[1]),b=stoi(argv[2]),c=stoi(argv[3]);
        auto ans=ctr.count(a,b,c);
        cerr<<"nodes="<<ctr.nodes<<"
";
        cout<<ans<<"
";
        return 0;
    }
    for(int a=0;a<=28;a++) for(int b=0;b<=28-a;b++){
        int c=28-a-b;
        auto ans=ctr.count(a,b,c);
        if(ans) cout<<a<<" "<<b<<" "<<c<<" -> "<<ans<<" nodes="<<ctr.nodes<<"
";
    }
}
