#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;

struct Counter {
    static constexpr int N0=8, E=28, W=103; // K8 + extension to vertex 8
    vector<pair<int,int>> edges;
    vector<array<int,2>> triPairs[E];
    uint64_t allow[E][3][W];
    vector<array<uint64_t,W>> masks; // indexed by count triple compressed
    int color[E];
    int target[3];
    long long nodes=0;

    static int id(int a,int b,int c){ return (a*9 + b)*9 + c; }

    Counter(){
        int idx[N0][N0]; memset(idx,-1,sizeof(idx));
        for(int i=0;i<N0;i++) for(int j=i+1;j<N0;j++){
            idx[i][j]=idx[j][i]=edges.size();
            edges.push_back({i,j});
        }
        for(int e=0;e<E;e++){
            auto [u,v]=edges[e];
            for(int w=0;w<N0;w++) if(w!=u && w!=v){
                int e1=idx[min(u,w)][max(u,w)], e2=idx[min(v,w)][max(v,w)];
                if(e1<e2) triPairs[e].push_back({e1,e2}); else triPairs[e].push_back({e2,e1});
            }
            sort(triPairs[e].begin(), triPairs[e].end(), [](auto&a,auto&b){return a[0]==b[0]?a[1]<b[1]:a[0]<b[0];});
            triPairs[e].erase(unique(triPairs[e].begin(), triPairs[e].end(), [](auto&a,auto&b){return a[0]==b[0]&&a[1]==b[1];}), triPairs[e].end());
        }
        memset(allow,0,sizeof(allow));
        masks.resize(9*9*9);
        for(auto &arr:masks) arr.fill(0);
        for(int code=0; code<6561; code++){
            int t=code,x[N0];
            int cnt[3]={0,0,0};
            for(int i=0;i<N0;i++){ x[i]=t%3; cnt[x[i]]++; t/=3; }
            for(int e=0;e<E;e++){
                auto [u,v]=edges[e];
                for(int c=0;c<3;c++) if(!(x[u]==c && x[v]==c)) allow[e][c][code>>6] |= 1ULL<<(code&63);
            }
            masks[id(cnt[0],cnt[1],cnt[2])][code>>6] |= 1ULL<<(code&63);
        }
        memset(color,-1,sizeof(color));
    }

    ull dfs(int rem, int c0, int c1, int c2, const uint64_t *bits){
        nodes++;
        int need0 = target[0]-c0, need1 = target[1]-c1, need2 = target[2]-c2;
        if(need0<0||need1<0||need2<0) return 0;
        if(need0>rem+8 || need1>rem+8 || need2>rem+8) return 0;
        if(c0+rem < target[0]-8) return 0; // weak lower bounds from remaining K8 edges?
        if(c1+rem < target[1]-8) return 0;
        if(c2+rem < target[2]-8) return 0;
        if(rem==0){
            if(need0>8||need1>8||need2>8) return 0;
            auto &mask = masks[id(need0,need1,need2)];
            ull cnt=0; for(int w=0;w<W;w++) cnt += __builtin_popcountll(bits[w] & mask[w]);
            return cnt;
        }
        int best=-1,bestOpts=4,bestScore=-1; bool bestForb[3]={};
        for(int e=0;e<E;e++) if(color[e]==-1){
            bool forb[3]={false,false,false}; int score=0, opts=0;
            for(auto &pr: triPairs[e]){
                int a=color[pr[0]], b=color[pr[1]];
                if(a!=-1 && a==b){ if(!forb[a]) score++; forb[a]=true; }
            }
            for(int c=0;c<3;c++) if(!forb[c]) opts++;
            if(opts<bestOpts || (opts==bestOpts && score>bestScore)){
                best=e; bestOpts=opts; bestScore=score;
                for(int c=0;c<3;c++) bestForb[c]=forb[c];
                if(opts==1 && score==3) break;
            }
        }
        uint64_t nb[W];
        ull total=0;
        for(int c=0;c<3;c++) if(!bestForb[c]){
            bool any=false;
            for(int w=0;w<W;w++){ nb[w]=bits[w] & allow[best][c][w]; any |= (nb[w]!=0); }
            if(!any) continue;
            color[best]=c;
            total += dfs(rem-1, c0+(c==0), c1+(c==1), c2+(c==2), nb);
            color[best]=-1;
        }
        return total;
    }

    ull count(int a,int b,int c){
        target[0]=a; target[1]=b; target[2]=c;
        uint64_t full[W]; for(int i=0;i<W;i++) full[i]=~0ULL; full[W-1]=(1ULL<<33)-1ULL;
        nodes=0;
        return dfs(E,0,0,0,full);
    }
};

int main(int argc,char**argv){
    Counter ctr;
    int a=stoi(argv[1]),b=stoi(argv[2]),c=stoi(argv[3]);
    auto st=chrono::steady_clock::now();
    auto ans=ctr.count(a,b,c);
    auto en=chrono::steady_clock::now();
    cerr<<"nodes="<<ctr.nodes<<" time="<<chrono::duration<double>(en-st).count()<<"\n";
    cout<<ans<<"\n";
}
